import { toRaw } from 'vue';
import { ensureStrings } from '@/strings';
import type { ChatGroup, Endpoint } from '@/01-models/types';
import type { LmProvider } from '@/01-models/lm';
import { areEndpointsEqual, isHttpEndpoint, isSupportedEndpoint } from '@/01-models/endpoint';
import { loadLmProvider } from '@/features/lm/providerFactory';
import { useGlobalEvents } from '@/composables/useGlobalEvents';
import { useSettings } from '@/composables/useSettings';
import {
  availableModels,
  chatRuntimeStore,
  currentChatRef,
  getLiveChatById,
  rootItems,
  triggerCurrentChat,
} from '@/composables/chat/global/chat-core-singletons';
import type { ChatId } from '@/01-models/ids';
import {
  resolveChatEndpointForChat,
  resolveGlobalEndpoint,
} from '@/composables/chat/chat-model-helpers';

export async function fetchModelsForChat({
  chatId,
  errorSource,
}: {
  chatId: ChatId,
  errorSource: string,
}): Promise<string[]> {
  const { settings } = useSettings();
  const mutableChat = getLiveChatById({ chatId });
  if (mutableChat === null) {
    return [];
  }

  chatRuntimeStore.startTask({ key: { kind: 'fetch', chatId: mutableChat.id } });
  try {
    const endpoint = resolveChatEndpointForChat({
      chat: mutableChat,
      chatGroups: collectChatGroups({ items: rootItems.value }),
      settings: settings.value,
    });
    const models = await fetchModelsForEndpoint({
      endpoint,
      errorSource,
    });
    const currentEndpoint = resolveChatEndpointForChat({
      chat: mutableChat,
      chatGroups: collectChatGroups({ items: rootItems.value }),
      settings: settings.value,
    });
    const endpointIsCurrent = areEndpointsEqual({ left: endpoint, right: currentEndpoint });

    if (
      endpointIsCurrent
      && currentChatRef.value !== null
      && toRaw(currentChatRef.value).id === mutableChat.id
    ) {
      availableModels.value = models;
    }

    if (
      endpointIsCurrent
      && isSupportedEndpoint(endpoint)
      && mutableChat.modelId
      && !models.includes(mutableChat.modelId)
      && !(endpoint.type === 'llama_cpp_browser' && /^(?:hf\.co|host)\//.test(mutableChat.modelId))
      // RPC can still resolve saved Host file references after its catalog starts
      // publishing variant names; an absent listing must not erase that choice.
      && !(endpoint.type === 'naidan_rpc' && mutableChat.modelId.startsWith('host/'))
    ) {
      let replacement = '';
      switch (endpoint.type) {
      case 'llama_cpp_browser': {
        // Existing chats selected a GGUF filename before model directories became
        // the public selection name. Resolve only its exact listed directory.
        if (/^.+\.gguf$/i.test(mutableChat.modelId)) {
          const directory = `${mutableChat.modelId.slice(0, -5)}-GGUF`;
          if (models.includes(directory)) replacement = directory;
        }
        break;
      }
      case 'naidan_rpc': case 'openai': case 'ollama': case 'transformers_js': case 'browser_provided_lm': break;
      default: { const exhaustive: never = endpoint; throw new Error(`Unhandled endpoint: ${exhaustive}`); }
      }
      mutableChat.modelId = replacement;
      mutableChat.updatedAt = Date.now();
      triggerCurrentChat({ chatId: mutableChat.id });
    }

    return models;
  } finally {
    chatRuntimeStore.finishTask({ key: { kind: 'fetch', chatId: mutableChat.id } });
  }
}

export async function fetchModelsForGlobalEndpoint({
  errorSource,
}: {
  errorSource: string,
}): Promise<string[]> {
  const { settings } = useSettings();
  chatRuntimeStore.startTask({ key: { kind: 'fetch', chatId: undefined } });
  try {
    const endpoint = resolveGlobalEndpoint({
      settings: settings.value,
    });
    const models = await fetchModelsForEndpoint({
      endpoint,
      errorSource,
    });
    const currentEndpoint = resolveGlobalEndpoint({
      settings: settings.value,
    });
    if (areEndpointsEqual({ left: endpoint, right: currentEndpoint })) {
      availableModels.value = models;
    }
    return models;
  } finally {
    chatRuntimeStore.finishTask({ key: { kind: 'fetch', chatId: undefined } });
  }
}

export async function fetchModelsForEndpoint({
  endpoint,
  errorSource,
}: {
  endpoint: Endpoint,
  errorSource: string,
}): Promise<string[]> {
  if (!isSupportedEndpoint(endpoint)) return [];
  if (isHttpEndpoint(endpoint) && endpoint.url === '') {
    return [];
  }

  const { addErrorEvent } = useGlobalEvents();

  try {
    const provider = await loadProviderForEndpoint({ endpoint });
    const models = await provider.listModels({ signal: undefined });
    return Array.isArray(models) ? models : [];
  } catch (error) {
    addErrorEvent({
      source: errorSource,
      message: await ensureStrings.chatModelFetch__failed_to_fetch_models_for_resolution(),
      details: error instanceof Error ? error.message : String(error),
    });
    return [];
  }
}

function collectChatGroups({
  items,
}: {
  items: typeof rootItems.value,
}): ChatGroup[] {
  return items.flatMap((item) => {
    switch (item.type) {
    case 'chat':
      return [];
    case 'chat_group':
      return [item.chatGroup];
    default: {
      const _ex: never = item;
      throw new Error(`Unhandled sidebar item type: ${_ex}`);
    }
    }
  });
}

async function loadProviderForEndpoint({
  endpoint,
}: {
  endpoint: Endpoint,
}): Promise<LmProvider> {
  const { settings } = useSettings();
  return await loadLmProvider({
    endpoint,
    fakeLmDebugModeStatus: settings.value.experimental?.fakeLm ?? 'disabled',
  });
}

